#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LEN 1024

static void build_histogram(const char *s, int hist[256])
{
    for ( ; *s != '\0'; ++s )
    {
        unsigned char c = (unsigned char)*s;
        if (c == ' ') continue;
        if ('A' <= c && c <= 'Z') c = c + ('a' - 'A');
        ++hist[c];
    }
}

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    if (strlen(argv[1]) >= MAX_LEN || strlen(argv[2]) >= MAX_LEN) {
        puts("TOO_LONG");
        return 0;
    }
    int hist1[256] = {0};
    int hist2[256] = {0};
    build_histogram(argv[1], hist1);
    build_histogram(argv[2], hist2);
    for (int i = 0; i < 256; ++i) {
        if (hist1[i] != hist2[i]) {
            puts("NOT_ANAGRAM");
            return 0;
        }
    }
    puts("ANAGRAM");
    return 0;
}
